CAMBIOS = {'provisioning/vault/argus-vault-unseal': [('#!/bin/bash\n# provisioning/vault/argus-vault-unseal — [VAULT-ARRANQUE-D322] desellado del Vault del lab (opción c: la clave de\n# desellado vive en disco, /etc/vault.d/unseal.key, root 0600; sale por stdin, nunca por argv). SOLO laboratorio: en\n# producción no hay clave en disco (ADR-060, sección 7 «8e.4d»). Lo pone scripts/etcd_ha/vault_arranque_instalar.sh en\n# /usr/local/sbin/ y lo lanza argus-vault-unseal.service, ligada a vault.service: cada arranque de Vault, también el de un\n# Restart=on-failure, lo dessella (medido DAY322: ligada a multi-user.target, un Vault caído en el arranque se quedaba\n# sellado y solo lo desellaba, de rebote, el `systemctl start` del aprovisionador etcd-server-unit).\n# Identidad propia (DAY322, decisión b de Alonso): CN=argus-vault-unseal, OU=argus-vault-unseal, SIN ninguna política\n# en Vault: sys/seal-status y sys/unseal no la piden; el listener exige certificado de cliente solo para el TLS. Antes\n# usaba el del etcd-server, la identidad que lee y escribe las claves HMAC.\n# Cada curl es hijo directo de este script (nada de curl en tuberías dentro de $(...), que añadiría un subshell): la\n# regla de Falco del dueño de la clave (provisioning/falco/argus_lab.yaml) pide padre bash e hijo de pid 1 (systemd).\n# Vault sin inicializar (primer aprovisionamiento, antes de que vault-server haga el init): nada que desellar, rc 0.\nset -u\nLC_ALL=C; export LC_ALL\nC="--cacert /etc/vault.d/tls/ca.crt --cert /etc/argus-pki/argus-vault-unseal.crt --key /etc/argus-pki/argus-vault-unseal.key"\nU=https://127.0.0.1:8200\nESTADO=""; RC=0\nestado() { ESTADO=$(curl -s --max-time 3 $C "$U/v1/sys/seal-status"); RC=$?; [ "$RC" = 0 ] || ESTADO=""; }\ncampo() { python3 -c \'import json,sys; print(json.loads(sys.argv[1]).get(sys.argv[2]))\' "$ESTADO" "$1" 2>/dev/null; }\nfor _ in $(seq 1 30); do estado; [ -n "$ESTADO" ] && break; sleep 1; done\n[ -n "$ESTADO" ] || { echo "[VAULT-UNSEAL] FALLA: Vault no responde en 30 s en $U (sys/seal-status); último curl rc=$RC" \\\n  "(7: nadie escucha; 35 o 56: el TLS rechaza el certificado, ¿/etc/argus-pki/argus-vault-unseal.crt de otra CA?)"; exit 1; }\nif [ "$(campo initialized)" = False ]; then\n  echo "[VAULT-UNSEAL] Vault sin inicializar: nada que desellar (lo inicializa el aprovisionador vault-server)"; exit 0\nfi\nif [ "$(campo sealed)" = True ]; then\n  [ -s /etc/vault.d/unseal.key ] || { echo "[VAULT-UNSEAL] FALLA: sellado y sin /etc/vault.d/unseal.key"; exit 1; }\n  python3 -c \'import json; print(json.dumps({"key": open("/etc/vault.d/unseal.key").read().strip()}))\' \\\n    | curl -s --max-time 5 $C -X PUT --data-binary @- -o /dev/null "$U/v1/sys/unseal"\n  estado\nfi\n[ "$(campo sealed)" = False ] || { echo "[VAULT-UNSEAL] FALLA: sigue sellado"; exit 1; }\necho "[VAULT-UNSEAL] Vault desellado"\n', '#!/usr/bin/python3 -I\n# provisioning/vault/argus-vault-unseal — [VAULT-ARRANQUE-D322] desellado del Vault del lab (opción c: la clave de\n# desellado vive en disco, /etc/vault.d/unseal.key, root 0600; va en el cuerpo de la petición, nunca en argv). SOLO\n# laboratorio: en producción no hay clave en disco (ADR-060, sección 7). Lo pone scripts/etcd_ha/vault_arranque_instalar.sh\n# en /usr/local/sbin/ y lo lanza argus-vault-unseal.service, ligada a vault.service: cada arranque de Vault, también el\n# de un Restart=on-failure, lo dessella (medido DAY322: ligada a multi-user.target, un Vault caído en el arranque se\n# quedaba sellado).\n# Identidad propia (DAY322, decisión b de Alonso): CN=argus-vault-unseal, OU=argus-vault-unseal, SIN ninguna política\n# en Vault: sys/seal-status y sys/unseal no la piden; el listener exige certificado de cliente solo para el TLS.\n# [DESELLADO-PY-D326] Python estándar en vez de bash + curl (decisión de Alonso DAY326: sin curl; `vault operator unseal`\n# solo acepta la clave como argumento, visible en el proceso). Falco lo reconoce por binario, argumentos y fichero, no\n# por el árbol de procesos: medido DAY326, al arrancar la VM Falco tarda ~2 s en conocer a los procesos nuevos y la\n# regla vieja (padre bash, abuelo pid 1) daba CRITICAL con padre=<NA>. Los plazos son los del script de bash (DAY322).\n# Vault sin inicializar (primer aprovisionamiento, antes de que vault-server haga el init): nada que desellar, rc 0.\nimport http.client\nimport json\nimport ssl\nimport sys\nimport time\n\nTAG = "[VAULT-UNSEAL]"\nHOST, PUERTO = "127.0.0.1", 8200\nCA = "/etc/vault.d/tls/ca.crt"\nCRT = "/etc/argus-pki/argus-vault-unseal.crt"\nKEY = "/etc/argus-pki/argus-vault-unseal.key"\nCLAVE = "/etc/vault.d/unseal.key"\nINTENTOS, PAUSA_S = 30, 1                 # hasta 30 s a que Vault responda (como el script de bash, DAY322)\nTIMEOUT_ESTADO_S, TIMEOUT_DESELLO_S = 3, 5\nMAX_RESPUESTA = 65536\n\n\nclass Fallo(Exception):\n    pass\n\n\ndef pedir(metodo, ruta, cuerpo, timeout_s):\n    """(status, objeto JSON o None) por HTTPS con el certificado del desellado. Fallo si no hay respuesta."""\n    c = None\n    try:\n        ctx = ssl.create_default_context(cafile=CA)\n        ctx.minimum_version = ssl.TLSVersion.TLSv1_2\n        ctx.load_cert_chain(CRT, KEY)\n        c = http.client.HTTPSConnection(HOST, PUERTO, context=ctx, timeout=timeout_s)\n        c.request(metodo, ruta, body=cuerpo, headers={"Content-Type": "application/json"} if cuerpo else {})\n        r = c.getresponse()\n        datos = r.read(MAX_RESPUESTA)\n    except (OSError, http.client.HTTPException, ssl.SSLError) as e:\n        raise Fallo(str(e)[:200]) from None\n    finally:\n        if c is not None:\n            c.close()\n    try:\n        return r.status, json.loads(datos.decode("utf-8"))\n    except (UnicodeDecodeError, ValueError):\n        return r.status, None\n\n\ndef estado(pedir):\n    """El JSON de sys/seal-status, o None si Vault no responde (aún)."""\n    try:\n        st, j = pedir("GET", "/v1/sys/seal-status", None, TIMEOUT_ESTADO_S)\n    except Fallo as e:\n        return None, str(e)\n    if st != 200 or not isinstance(j, dict):\n        return None, f"HTTP {st}"\n    return j, ""\n\n\ndef leer_clave(ruta=CLAVE):\n    try:\n        with open(ruta, encoding="ascii") as f:\n            k = f.read().strip()\n    except (OSError, UnicodeDecodeError):\n        k = ""\n    return k\n\n\ndef main(pedir=pedir, dormir=time.sleep, leer_clave=leer_clave):\n    e, ultimo = None, ""\n    for i in range(INTENTOS):\n        e, ultimo = estado(pedir)\n        if e is not None:\n            break\n        if i + 1 < INTENTOS:\n            dormir(PAUSA_S)\n    if e is None:\n        print(f"{TAG} FALLA: Vault no responde en {INTENTOS * PAUSA_S} s en https://{HOST}:{PUERTO} (sys/seal-status); "\n              f"último error: {ultimo} (¿nadie escucha, o el TLS rechaza {CRT}, de otra CA?)")\n        return 1\n    if e.get("initialized") is False:\n        print(f"{TAG} Vault sin inicializar: nada que desellar (lo inicializa el aprovisionador vault-server)")\n        return 0\n    if e.get("sealed") is True:\n        k = leer_clave()\n        if not k:\n            print(f"{TAG} FALLA: sellado y sin {CLAVE} (o vacía o ilegible)")\n            return 1\n        try:\n            st, _ = pedir("PUT", "/v1/sys/unseal", json.dumps({"key": k}).encode("ascii"), TIMEOUT_DESELLO_S)\n        except Fallo as x:\n            st = f"sin respuesta ({x})"\n        del k\n        if st != 200:\n            print(f"{TAG} AVISO: sys/unseal respondió {st}")\n        e, ultimo = estado(pedir)\n        if e is None:\n            print(f"{TAG} FALLA: tras desellar, Vault no responde a sys/seal-status ({ultimo})")\n            return 1\n    if e.get("sealed") is not False:\n        print(f"{TAG} FALLA: sigue sellado")\n        return 1\n    print(f"{TAG} Vault desellado")\n    return 0\n\n\nif __name__ == "__main__":\n    sys.exit(main())\n', 1)], 'provisioning/falco/argus_lab.yaml': [('# [VAULT-ARRANQUE-D322] el desellado del Vault del lab (provisioning/vault/argus-vault-unseal, identidad propia\n# CN=argus-vault-unseal sin políticas en Vault): lo lanza systemd (argus-vault-unseal.service), así que el bash del script\n# es hijo de pid 1 y cada curl es hijo directo del script. Solo su clave: la del etcd-server ya no la usa.\n- macro: argus_lab_es_desellado\n  condition: >\n    (proc.exepath = /usr/bin/curl and proc.pexepath = /usr/bin/bash and proc.apid[2] = 1 and\n     fd.name = /etc/argus-pki/argus-vault-unseal.key)\n', '# [VAULT-ARRANQUE-D322] el desellado del Vault del lab (provisioning/vault/argus-vault-unseal, identidad propia\n# CN=argus-vault-unseal sin políticas en Vault), lanzado por argus-vault-unseal.service. Solo su clave TLS y la clave de\n# desellado. [DESELLADO-PY-D326] Python estándar (#!/usr/bin/python3 -I), reconocido por binario, ARGUMENTOS y fichero:\n# medido DAY326, al arrancar la VM Falco tarda ~2 s en conocer a los procesos nuevos y la regla vieja (curl, padre bash,\n# abuelo pid 1) daba CRITICAL con padre=<NA>. proc.args, no proc.name: el kernel corta el nombre a 15 caracteres\n# (argus-vault-uns). Python de Debian 12: con Debian 13 vuelve a dar CRITICAL y se mide.\n- macro: argus_lab_es_desellado\n  condition: >\n    (proc.exepath = /usr/bin/python3.11 and proc.args = "-I /usr/local/sbin/argus-vault-unseal" and\n     fd.name in (/etc/argus-pki/argus-vault-unseal.key, /etc/vault.d/unseal.key))\n', 1), ('    (fd.name glob "/etc/argus-pki/*.key" or fd.name glob "/etc/vault.d/tls/*.key" or\n', '    (fd.name glob "/etc/argus-pki/*.key" or fd.name glob "/etc/vault.d/tls/*.key" or\n     fd.name = /etc/vault.d/unseal.key or\n', 1)], 'Makefile': [('\t@$(EMECAS_PASO) test-clave-bronce -- $(MAKE) test-clave-bronce\n', '\t@$(EMECAS_PASO) test-clave-bronce -- $(MAKE) test-clave-bronce\n\t@$(EMECAS_PASO) test-vault-unseal -- $(MAKE) test-vault-unseal\n', 1), ('test-clave-bronce:\n\t@vagrant ssh defender -c "cd /tmp && python3 -I /vagrant/scripts/bronze_key/test_clave_bronce.py"\n', 'test-clave-bronce:\n\t@vagrant ssh defender -c "cd /tmp && python3 -I /vagrant/scripts/bronze_key/test_clave_bronce.py"\n\n# [DESELLADO-PY-D326] (Mac): tests del desellado del Vault del lab (provisioning/vault/argus-vault-unseal; unittest, sin\n# red ni Vault) con el Python de control-1, donde corre: espera a Vault, sin inicializar, desellado y clave sin salir.\n.PHONY: test-vault-unseal\ntest-vault-unseal:\n\t@vagrant ssh control-1 -c "cd /tmp && python3 -I /vagrant/provisioning/vault/test_argus_vault_unseal.py"\n', 1)]}
NUEVOS = {'provisioning/vault/test_argus_vault_unseal.py': '#!/usr/bin/python3 -I\n# test_argus_vault_unseal.py — [DESELLADO-PY-D326] tests del desellado del Vault del lab (provisioning/vault/\n# argus-vault-unseal) con la biblioteca estándar (unittest), sin red ni Vault: las peticiones HTTPS se simulan. Prueban\n# la espera a que Vault responda, Vault sin inicializar, el desellado con la clave del fichero y que la clave nunca sale\n# por la salida. El desellado real lo prueban el arranque de la VM y lab-e2e-vigilancia (C7).\n#   python3 -I provisioning/vault/test_argus_vault_unseal.py      (make test-vault-unseal, en control-1)\nimport contextlib\nimport importlib.machinery\nimport importlib.util\nimport io\nimport json\nimport os\nimport sys\nimport unittest\n\nsys.dont_write_bytecode = True  # se ejecuta desde /vagrant: sin __pycache__ en el repo\nAQUI = os.path.dirname(os.path.abspath(__file__))\n_l = importlib.machinery.SourceFileLoader("argus_vault_unseal", os.path.join(AQUI, "argus-vault-unseal"))\n_spec = importlib.util.spec_from_loader("argus_vault_unseal", _l)\ndu = importlib.util.module_from_spec(_spec)\n_l.exec_module(du)\n\nCLAVE = "IXyR0OJnSFobekZMMCKCoVEpT7wI6l+USMzE3IcyDyo="\n\n\nclass Vault:\n    """Vault simulado: no responde las primeras `mudo` veces; luego contesta según su estado."""\n\n    def __init__(self, mudo=0, inicializado=True, sellado=True, desella=True, status_unseal=200):\n        self.mudo, self.inicializado, self.sellado = mudo, inicializado, sellado\n        self.desella, self.status_unseal = desella, status_unseal\n        self.pedidos = []\n\n    def pedir(self, metodo, ruta, cuerpo, timeout_s):\n        self.pedidos.append((metodo, ruta, cuerpo, timeout_s))\n        if ruta == "/v1/sys/seal-status":\n            if self.mudo > 0:\n                self.mudo -= 1\n                raise du.Fallo("[Errno 111] Connection refused")\n            return 200, {"initialized": self.inicializado, "sealed": self.sellado}\n        if ruta == "/v1/sys/unseal" and metodo == "PUT":\n            if self.desella and json.loads(cuerpo) == {"key": CLAVE}:\n                self.sellado = False\n            return self.status_unseal, {"sealed": self.sellado}\n        return 404, None\n\n\ndef correr(v, clave=CLAVE):\n    pausas = []\n    out = io.StringIO()\n    with contextlib.redirect_stdout(out):\n        rc = du.main(pedir=v.pedir, dormir=pausas.append, leer_clave=lambda: clave)\n    return rc, out.getvalue(), pausas\n\n\nclass Desellado(unittest.TestCase):\n    def test_sellado_se_dessella_con_la_clave_del_fichero_en_el_cuerpo(self):\n        v = Vault()\n        rc, out, _ = correr(v)\n        self.assertEqual((rc, out), (0, "[VAULT-UNSEAL] Vault desellado\\n"))\n        puts = [p for p in v.pedidos if p[0] == "PUT"]\n        self.assertEqual(puts, [("PUT", "/v1/sys/unseal", json.dumps({"key": CLAVE}).encode(), du.TIMEOUT_DESELLO_S)])\n\n    def test_ya_desellado_no_manda_la_clave(self):\n        v = Vault(sellado=False)\n        rc, out, _ = correr(v)\n        self.assertEqual((rc, out), (0, "[VAULT-UNSEAL] Vault desellado\\n"))\n        self.assertFalse([p for p in v.pedidos if p[0] == "PUT"])\n\n    def test_sin_inicializar_no_hace_nada(self):\n        v = Vault(inicializado=False)\n        rc, out, _ = correr(v)\n        self.assertEqual(rc, 0)\n        self.assertIn("Vault sin inicializar", out)\n        self.assertFalse([p for p in v.pedidos if p[0] == "PUT"])\n\n    def test_espera_a_que_vault_responda(self):\n        v = Vault(mudo=5)\n        rc, out, pausas = correr(v)\n        self.assertEqual(rc, 0)\n        self.assertEqual(pausas, [du.PAUSA_S] * 5)\n\n    def test_vault_mudo_falla_tras_los_intentos(self):\n        v = Vault(mudo=10 ** 6)\n        rc, out, pausas = correr(v)\n        self.assertEqual(rc, 1)\n        self.assertIn("FALLA: Vault no responde en 30 s", out)\n        self.assertIn("Connection refused", out)\n        self.assertEqual(len(pausas), du.INTENTOS - 1)\n\n    def test_sin_clave_falla_y_no_pide_desellar(self):\n        v = Vault()\n        rc, out, _ = correr(v, clave="")\n        self.assertEqual(rc, 1)\n        self.assertIn("FALLA: sellado y sin /etc/vault.d/unseal.key", out)\n        self.assertFalse([p for p in v.pedidos if p[0] == "PUT"])\n\n    def test_clave_mala_sigue_sellado_y_la_clave_no_sale_por_la_salida(self):\n        v = Vault(desella=False, status_unseal=400)\n        rc, out, _ = correr(v)\n        self.assertEqual(rc, 1)\n        self.assertIn("FALLA: sigue sellado", out)\n        self.assertIn("AVISO: sys/unseal respondió 400", out)\n        self.assertNotIn(CLAVE, out)\n        self.assertNotIn(CLAVE[:12], out)\n\n    def test_leer_clave_quita_el_salto_y_da_vacio_si_no_existe(self):\n        import tempfile\n        d = tempfile.mkdtemp()\n        r = os.path.join(d, "unseal.key")\n        with open(r, "w") as f:\n            f.write(CLAVE + "\\n")\n        self.assertEqual(du.leer_clave(r), CLAVE)\n        self.assertEqual(du.leer_clave(os.path.join(d, "no-existe")), "")\n\n\nif __name__ == "__main__":\n    unittest.main(verbosity=2)\n'}


def sha(b):
    return hashlib.sha256(b).hexdigest()


def main():
    if len(sys.argv) != 2 or sys.argv[1] not in ("--check", "--apply"):
        print(f"{TAG} uso: python3 -I scripts/etcd_ha/d326_f2e_desellado.py --check | --apply", file=sys.stderr)
        return 2
    if not (os.path.isfile("Vagrantfile") and os.path.isdir(".git")):
        print(f"{TAG} FALLA: ejecútalo desde la raíz del repo", file=sys.stderr)
        return 1
    nuevos, ya = {}, 0
    for p in sorted(FINAL):
        existe = os.path.exists(p)
        if existe and sha(open(p, "rb").read()) == FINAL[p]:
            print(f"{TAG} {p}: ya aplicado")
            ya += 1
            continue
        if p in NUEVOS:
            if existe:
                print(f"{TAG} FALLA: {p} ya existe y no es el esperado; nada escrito", file=sys.stderr)
                return 1
            r = NUEVOS[p].encode("utf-8")
            que = "nuevo"
        else:
            if not existe:
                print(f"{TAG} FALLA: falta {p}; nada escrito", file=sys.stderr)
                return 1
            b = open(p, "rb").read()
            if sha(b) != INICIO[p]:
                print(f"{TAG} FALLA: {p} sha256 {sha(b)} no es el de partida {INICIO[p]} ni el final; nada escrito",
                      file=sys.stderr)
                return 1
            s = b.decode("utf-8")
            for i, (a, n, veces) in enumerate(CAMBIOS[p]):
                c = s.count(a)
                if c != veces:
                    print(f"{TAG} FALLA: {p} ancla {i} aparece {c} veces (se exigen {veces}); nada escrito",
                          file=sys.stderr)
                    return 1
                s = s.replace(a, n)
            r = s.encode("utf-8")
            que = f"{len(CAMBIOS[p])} anclas con sus veces exactas"
        if sha(r) != FINAL[p]:
            print(f"{TAG} FALLA: {p} resultado {sha(r)} no es el esperado {FINAL[p]}; nada escrito", file=sys.stderr)
            return 1
        nuevos[p] = r
        print(f"{TAG} {p}: {que}; resultado {FINAL[p][:16]}")
    if sys.argv[1] == "--check":
        print(f"{TAG} CHECK OK: {len(nuevos)} por aplicar, {ya} ya aplicados")
        return 0
    for p, r in nuevos.items():
        modo = os.stat(p).st_mode if os.path.exists(p) else 0o100644
        tmp = p + ".d326etmp"
        with open(tmp, "wb") as f:
            f.write(r)
        os.chmod(tmp, modo & 0o7777)
        os.replace(tmp, p)
    print(f"{TAG} APLICADO: {len(nuevos)} escritos, {ya} ya estaban.")
    return 0


if __name__ == "__main__":
    sys.exit(main())
